import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"@saasweave/server","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/apps/server.md","filePath":"reference/apps/server.md","lastUpdated":null}'),o={name:"reference/apps/server.md"};function d(i,e,l,n,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s(`<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/apps/server/README.md" target="_blank" rel="noreferrer"><code>apps/server/README.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="saasweave-server" tabindex="-1">@saasweave/server <a class="header-anchor" href="#saasweave-server" aria-label="Permalink to &quot;@saasweave/server&quot;">​</a></h1><p>Node.js Hono server: oRPC API, Better Auth handler, Stripe webhooks, and media upload routes.</p><h2 id="always-on" tabindex="-1">Always on <a class="header-anchor" href="#always-on" aria-label="Permalink to &quot;Always on&quot;">​</a></h2><ul><li>oRPC + OpenAPI (<code>/server/rpc</code>, <code>/server/docs</code> when enabled)</li><li>Better Auth at <code>/server/auth/*</code></li><li>Health endpoints (<code>/server/health/live</code>, <code>/server/health/ready</code>)</li><li>Maintenance mode middleware</li><li>Auth rate limiting</li><li><code>GET /server/auth/providers</code> - public OAuth availability flags</li><li>Media routes at <code>/server/media/*</code> (local disk or MinIO presigned)</li></ul><h2 id="optional-env-gated" tabindex="-1">Optional / env-gated <a class="header-anchor" href="#optional-env-gated" aria-label="Permalink to &quot;Optional / env-gated&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Enabled when</th></tr></thead><tbody><tr><td>OpenAPI Scalar docs</td><td><code>ENABLE_OPEN_API_DOCS=true</code></td></tr><tr><td>Redis-backed rate limit cache</td><td><code>REDIS_URL</code></td></tr><tr><td>MinIO presigned uploads</td><td>All <code>MINIO_*</code> credentials set</td></tr><tr><td>Local disk uploads</td><td>MinIO unset; uses <code>MEDIA_UPLOAD_DIR</code></td></tr><tr><td>Stripe webhooks</td><td><code>STRIPE_SECRET_KEY</code> + <code>STRIPE_WEBHOOK_SECRET</code></td></tr><tr><td>OAuth providers</td><td><code>GOOGLE_*</code> / <code>GITHUB_*</code></td></tr><tr><td>Platform admin emails</td><td><code>PLATFORM_ADMIN_EMAILS</code></td></tr></tbody></table><p>Stripe webhook request bodies are capped at 1 MiB before signature verification. The server enforces the same limit for requests with <code>Content-Length</code> and for chunked request streams.</p><h2 id="key-modules" tabindex="-1">Key modules <a class="header-anchor" href="#key-modules" aria-label="Permalink to &quot;Key modules&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/index.ts              # Hono app, route mounting</span></span>
<span class="line"><span>src/middleware/platform.ts  # maintenance, rate limits</span></span>
<span class="line"><span>src/routes/media.ts       # signed upload + serve</span></span></code></pre></div><p>Route order matters: specific routes like <code>/auth/providers</code> must be registered <strong>before</strong> the <code>/auth/*</code> catch-all.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>See <a href="/SaaSWeave/reference/packages/env">packages/env/README.md</a> for the full server schema (<code>ENV_SERVER</code>).</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saasweave/server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Default: <a href="http://localhost:5000/server" target="_blank" rel="noreferrer">http://localhost:5000/server</a></p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><p>Built from <code>apps/server/Dockerfile</code>. Migrator target runs <code>db:migrate</code> before the server starts in Compose.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/SaaSWeave/reference/packages/api">packages/api</a> — router definitions</li><li><a href="/SaaSWeave/reference/packages/auth">packages/auth</a> — Better Auth instance</li></ul>`,20)])])}const v=a(o,[["render",d]]);export{u as __pageData,v as default};
